<?php
require __DIR__ . '/config/db.php';
require __DIR__ . '/includes/helpers.php';
require __DIR__ . '/includes/auth.php';
require_role(['admin', 'manager']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf_token($_POST['csrf_token'] ?? '')) { set_flash('error', 'Security validation failed. Refresh the page and try again.'); redirect_to('categories.php'); }
    $name = trim($_POST['name'] ?? ''); $description = trim($_POST['description'] ?? '');
    if ($name === '' || mb_strlen($name) > 100 || mb_strlen($description) > 255) { set_flash('error', 'Enter a category name (maximum 100 characters) and a description no longer than 255 characters.'); redirect_to('categories.php'); }
    try { $stmt=$pdo->prepare('INSERT INTO categories (name, description) VALUES (:name, :description)'); $stmt->execute([':name'=>$name, ':description'=>$description !== '' ? $description : null]); set_flash('success', 'Category created successfully.'); }
    catch (PDOException $e) { error_log('SmartShop category create failed: '.$e->getMessage()); set_flash('error', $e->getCode()==='23000' ? 'A category with that name already exists.' : 'The category could not be saved. Please try again.'); }
    redirect_to('categories.php');
}
$categories=$pdo->query('SELECT c.id,c.name,c.description,c.created_at,COUNT(p.id) AS product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();
$flash=get_flash();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Categories | SmartShop</title><link rel="stylesheet" href="Assets/css/style.css"><link rel="stylesheet" href="Assets/css/inventory.css"><link rel="stylesheet" href="Assets/css/enterprise-overrides.css"></head><body class="inventory-page"><header class="inv-topbar"><a class="inv-brand" href="dashboard.php">SmartShop <span>Inventory</span></a><?php require __DIR__ . '/includes/nav.php'; ?></header><main class="inv-container"><div class="inv-heading"><div><p class="eyebrow">PRODUCT ORGANIZATION</p><h1>Categories</h1><p class="muted">Group products into consistent categories for easier browsing and reporting.</p></div><a class="btn btn-plain" href="products.php">Back to products</a></div><?php if($flash): ?><div class="alert <?= e($flash['type']) ?>" role="status"><?= e($flash['message']) ?></div><?php endif; ?><div class="supplier-layout"><section class="inv-card supplier-form-card"><div class="card-title"><h2>Create category</h2></div><form method="post" class="supplier-form" action="categories.php"><?= csrf_input() ?><label>Category name *<input name="name" maxlength="100" required placeholder="e.g. Building materials"></label><label>Description<input name="description" maxlength="255" placeholder="Optional description"></label><button class="btn btn-primary" type="submit">Save category</button></form></section><section class="inv-card"><div class="card-title"><h2>Category directory <span class="muted">(<?= count($categories) ?>)</span></h2></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Description</th><th>Products</th><th>Created</th></tr></thead><tbody><?php if(!$categories): ?><tr><td colspan="4" class="empty-state">No categories have been created yet.</td></tr><?php endif; ?><?php foreach($categories as $category): ?><tr><td><strong><?= e($category['name']) ?></strong></td><td><?= e($category['description'] ?: '—') ?></td><td><?= number_format((int)$category['product_count']) ?></td><td><?= e(date('d M Y',strtotime($category['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></main></body></html>
